// Valida X-Edificia-Auth contra la variable de entorno EDIFICIA_API_SECRET.
// Extrae y expone el body para los nodos siguientes.
const items = $input.all();
const headers = items[0].json.headers;
const expectedSecret = $env.EDIFICIA_API_SECRET;
const receivedSecret = headers['x-edificia-auth'];

if (!expectedSecret) {
  throw new Error('EDIFICIA_API_SECRET environment variable is not configured in n8n.');
}

if (!receivedSecret || receivedSecret !== expectedSecret) {
  return [{ json: { isValid: false } }];
}

const body = items[0].json.body;
return [{ json: { isValid: true, ...body } }];

// Decodifica el contenido base64 de la plantilla y lo prepara como dato binario
// para que el nodo de Google Drive pueda subirlo.
// Nota: folderId se resuelve aquí desde $env para evitar el bug de n8n v3
// donde $env en campos __rl Resource Locator incluye el '=' del marcador de expresión.
const item = $input.first();
const payload = item.json.payload;

if (!payload || !payload.contentBase64) {
  throw new Error('payload.contentBase64 es obligatorio para UPLOAD_TEMPLATE.');
}
if (!payload.fileName) {
  throw new Error('payload.fileName es obligatorio para UPLOAD_TEMPLATE.');
}

const folderId = $env.GDRIVE_TEMPLATES_FOLDER_ID;
if (!folderId) {
  throw new Error('GDRIVE_TEMPLATES_FOLDER_ID environment variable is not configured in n8n.');
}

const buffer = Buffer.from(payload.contentBase64, 'base64');
const mimeType = payload.mimeType || 'application/vnd.openxmlformats-officedocument.wordprocessingml.template';

return [{
  json: { ...item.json, _folderId: folderId },
  binary: {
    data: await this.helpers.prepareBinaryData(buffer, payload.fileName, mimeType)
  }
}];

// Construye la respuesta de éxito para UPLOAD_TEMPLATE.
// storageKey = ID del fichero en Google Drive (opaco para la API).
const input = $input.first();
const original = $('Route Operation').first().json;
const driveFile = input.json;

return [{
  json: {
    apiVersion: '1.0',
    operation: 'UPLOAD_TEMPLATE',
    operationId: original.operationId,
    success: true,
    code: 'TEMPLATE_STORAGE_OK',
    message: 'Plantilla subida correctamente',
    provider: 'google-drive',
    timestampUtc: new Date().toISOString(),
    data: {
      storageKey: driveFile.id,
      fileName: driveFile.name,
      fileSizeBytes: original.payload?.fileSizeBytes ?? null,
      sha256: null,
      version: 1
    }
  }
}];

// Construye la respuesta para DELETE_TEMPLATE.
// Si el nodo de Drive devolvió error, responde TEMPLATE_NOT_FOUND (404 lógico).
const input = $input.first();
const original = $('Route Operation').first().json;
const hasError = !!input.json.error;

if (hasError) {
  return [{
    json: {
      apiVersion: '1.0',
      operation: 'DELETE_TEMPLATE',
      operationId: original.operationId,
      success: false,
      code: 'TEMPLATE_NOT_FOUND',
      message: 'La plantilla no existe en el almacenamiento',
      provider: 'google-drive',
      timestampUtc: new Date().toISOString(),
      data: { storageKey: original.payload?.storageKey, deleted: false }
    },
    _httpStatus: 404
  }];
}

return [{
  json: {
    apiVersion: '1.0',
    operation: 'DELETE_TEMPLATE',
    operationId: original.operationId,
    success: true,
    code: 'TEMPLATE_STORAGE_OK',
    message: 'Plantilla eliminada correctamente',
    provider: 'google-drive',
    timestampUtc: new Date().toISOString(),
    data: { storageKey: original.payload?.storageKey, deleted: true }
  },
  _httpStatus: 200
}];
